const amount=v=>Number.isFinite(v)?v.toLocaleString('zh-CN',{maximumFractionDigits:1}):'—';
const percent=v=>Number.isFinite(v)?(v*100).toFixed(1)+'%':'—';
const hints={upgrade:'以当前配装为参考，逐件分析未满级圣遗物；保留已有词条，三词条圣遗物会计入第四条及后续强化。',reshape:'保留主词条和四种副属性，自动推导可行初始档位，并按计算目标推荐两条指定词条；可逐件调整，结果为估计。',define:'选择套装、部位、主词条和两种指定副属性，分析祝圣定义的可能结果。'};

