   for(const [prefix,group,description]of [['idlePanel:','非战斗面板','常驻属性，不含队伍、战斗触发与手动增益'],['panel:','队伍战斗面板','沿用所选队伍的机制、共鸣和额外增益']])entries.push(...OPTIMIZER_PANEL_STATS.map(k=>({targetKey:member,value:prefix+k,name:optimizerStatName(k),category:'panel',group,description})));
