  entries.push({targetKey:'team',value:'combo',name:'固定动作合计',category:'team',description:ctx.scenario.combo?.length?'按当前队伍的固定动作合计':'请先在队伍页配置固定动作',disabled:!ctx.scenario.combo?.length});return entries;
