  return [...candidateCache].sort((a,b)=>{const x=results.get(a.id)?.value,y=results.get(b.id)?.value,metric=r=>prefs.sort==='gain'?(r?.average??-Infinity)-(r?.before??0):r?.probability??-Infinity;return (metric(y)-metric(x))||a.id-b.id;});
